def convert_to_utf8(self):
    result = []
    index = 0
    while index < len(self.binary_string):
        byte = self.binary_string[index:index + 8]
        byte_int = int(byte, 2)
        byte_utf8 = chr(byte_int)
        result.append(byte_utf8)
